  "bioavailability_prediction": "high",
  "confidence": "moderate",
  "revision_action": "strengthen",
  "supportive_card_ids": [
    "C30","C31","C33","C22","C23","C25","C26","C34","C37",
    "C08","C13","C14","C01","C02","C05","C11","C21","C24","C28","C36",
    "C135","C164","C236","C272","C229"
  ],
  "contradictory_card_ids": ["C180","C226"],
  "prediction_basis_card_ids": [
    "C30","C31","C33","C22","C23","C25","C26","C34","C37",
    "C08","C13","C14","C01","C02","C05","C11","C21","C24","C28","C36",
    "C180","C226","C236","C272"
  ],
  "claims": [
    {
      "claim": "L1 gold-context beta-blockers sharing the aryloxypropanolamine core have measured absolute oral bioavailability well above 20% in humans: pamatolol 64.9–103.5%, practolol 90–100%, pindolol approximately 53–100%, bufuralol 0.52–0.83, and diacetolol 0.30–0.43.",
      "card_ids": ["C30","C31","C33","C22","C23","C25","C26","C34","C37","C08","C13","C14","C01","C02","C05","C11","C21","C24","C28","C36"]
    },
    {
      "claim": "L5 C180 identifies talinolol as a beta-blocker with intestinal secretion and predominant basolateral-to-apical transport in Caco-2, and C226 shows P-gp inhibition increases celiprolol plasma concentration; rifampin-mediated P-gp induction could reduce talinolol absorption, but no record quantifies F below 20%.",
      "card_ids": ["C180","C226"]
    },
    {
      "claim": "L6 records show related polar beta-blockers have low hepatic intrinsic clearance or low extraction (atenolol in vivo intrinsic clearance 5 mL/min; practolol little affected by hepatic first-pass; atenolol microsomal CLint 1.08 mL/min/g liver), supporting that hepatic first-pass is not a major cause of sub-threshold F for this class.",
      "card_ids": ["C272","C236","C229"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "hepatic_clearance_metabolic_stability",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C236","C272","C229"]
    }
  ],
  "evidence_gaps": [
    "No direct measured absolute oral bioavailability for talinolol under rifampin co-treatment.",
    "No talinolol-specific rifampin interaction record; L3 lenvatinib-rifampin records are for a different molecule and lack an IV comparator.",
    "C180 establishes intestinal efflux direction but not magnitude; no F value or AUC ratio with rifampin is provided.",
    "L1 analog F values are for other beta-blockers without rifampin; transferability is limited by P-gp efflux and induction.",
    "L6 hepatic clearance records are for related beta-blockers, not talinolol itself, with species and assay differences.",
    "Physicochemical prior is mixed; high ionization may reduce passive permeability but is not threshold-negative evidence."
  ],
  "decision_summary": "L1/L2 gold evidence for structurally similar beta-blockers shows absolute F well above 20%; L6 adds low hepatic clearance for related polar beta-blockers, supporting limited first-pass loss. L5 C180 directly identifies talinolol as a P-gp efflux substrate and rifampin induction could reduce exposure, but no record demonstrates F < 20% under rifampin. Prediction remains high; confidence is moderate."
}

